from pathlib import Path
import json,base64,html,re,io
from fontTools import subset
root=Path(__file__).resolve().parents[1]
p=root/'outputs/video-notes/2.AI最底层的Raw-Model'
share=p/'share'
notes=json.loads((p/'work/notes-data.json').read_text(encoding='utf-8'))
manifest=json.loads((p/'work/scene-manifest.json').read_text(encoding='utf-8'))
def esc(x):return html.escape(str(x))
def paras(s):return ''.join('<p>'+esc(t)+'</p>' for t in s.split('\n\n'))
def img(n):
 f=Path(manifest['scenes'][n-1]['frame_path'])
 return 'data:image/jpeg;base64,'+base64.b64encode(f.read_bytes()).decode()
def diagram(full=False):
 top='<div class="flow"><div class="node">Token 列表<small>输入数字</small></div><div class="arrow">→</div><div class="node core">Raw Model<small>计算过程</small></div><div class="arrow">→</div><div class="node">概率分布<small>下一个 Token</small></div></div>'
 return top+('<div class="lower"><div class="training">语料<br><span>训练 / 微调 →</span></div><div class="weight"><span>↕ GPU</span><div class="node">权重矩阵<small>学习得到的参数</small></div></div></div>' if full else '')
slides=[]
def add(title,body,scene,hint='',kind=''):
 slides.append(dict(title=title,body=body,scene=scene,hint=hint,kind=kind))
add('AI 最底层的<br>Raw Model','<div class="title-line"></div><p class="subtitle" data-edit>理解大模型，从最原始的形态开始。</p><div class="title-meta">输入 · 权重 · 概率分布</div>',1,'从开场的连续提问进入课程。说明本课沿原讲解建立底层抽象，之后才进入模型服务。','title')
add('先看输入与输出',diagram()+'<p class="takeaway" data-edit>接收一串数字，计算下一个 Token 的可能性。</p>',1,'先只讲模型的接口直觉，不急着展开训练。输入是列表，输出是概率分布。上层工具如何使用它，留到后续课程。')
add('语言先变成数字','<div class="token-path"><span>自然语言</span><b>分词 →</b><code>[2, 3, 4, 5, 1, 8]</code></div><div class="duo"><div><em>中文</em><p data-edit>1 个字 ≈ 1.5 Token</p></div><div><em>英文</em><p data-edit>1 个单词 ≈ 1.3 Token</p></div></div><p class="fine" data-edit>本课采用的粗略估算；具体划分会因字词与分词方式而异。</p>',2,'强调“平均”二字，没有半个 Token。保留词根、前缀的例子。数组仅为课堂示意。')
add('输出是一组可能性','<div class="probability"><div class="prob-row"><strong>Token 15</strong><div><i style="width:70%"></i></div><b>0.7</b></div><div class="prob-row"><strong>Token 288</strong><div><i style="width:20%"></i></div><b>0.2</b></div><div class="prob-row remaining"><strong>其他 Token</strong><span>…</span></div></div><p class="takeaway" data-edit>模型在这里给出“概率分布”。</p><p class="fine">课堂示意数据</p>',3,'按原课先给15的0.7，再给288的0.2。不要把输出的分布直接说成已经选出的字，也不在本课补讲采样算法。')
add('“你好”后面会是什么？','<div class="continuation"><div class="prompt" data-edit>你好</div><div class="branch">↗<br>↘</div><div class="choices"><div data-edit>，</div><div data-edit>吗</div></div></div><p class="takeaway" data-edit>数字有对应关系，续写才呈现为自然语言。</p>',3,'按原课提问：返回的下一个Token是不是自然语言的一部分？这里的标点和“吗”没有与前页Token编号建立一一对应，不要擅自指定。')
add('上下文窗口有多长？','<div class="context-box"><span>Token List</span><div class="tokens">▯ ▯ ▯ ▯ ▯ ▯ ▯ ▯ ▯ ▯ ▯ ▯ ▯ ▯ ▯</div><div class="bracket">← 可容纳的 Token 数量 →</div></div><p class="takeaway" data-edit>最大上下文窗口：模型可处理的 Token 容量。</p><p class="fine" data-edit>K、M 在这里表示数量，不是磁盘空间。</p>',4,'原课用长度100和容量一万却传入两万的截断案例来建立直觉。“不会报错、自动截断”是原课表述，不能作为所有接口行为的保证。')
add('容量换算，先说明假设','<div class="big-stats"><div><em>128K</em><p>128,000 ÷ 1.5</p><strong>约 8.5 万中文字</strong></div><div><em>1M</em><p>1,000,000 ÷ 1.5</p><strong>约 66.7 万中文字</strong></div></div><p class="fine" data-edit>沿用本课“1 字 ≈ 1.5 Token”的假设；原课还列举了 256K。</p>',4,'讲清这些是数量换算，不是文本容量的固定保证。原课使用“八万多个”和“六十六万”的近似说法，本页保留估算性质。')
add('装得下 ≠ 处理得好','<div class="quote" data-edit>长对话里，<br>先前约定也可能被忘记。</div><div class="rule-row"><span data-edit>写完代码要提交</span><span data-edit>单个模块不超过 200 行</span></div><p class="takeaway" data-edit>相对独立的任务，尽量使用新的上下文。</p>',5,'保留两条代码规则的原始例子。继续解释原课为何提到子代理：用独立上下文处理任务。这里是讲者对使用现象的解释，不宣称所有遗忘都只有同一个原因。')
add('下载的模型，核心是权重','<div class="split"><div><p class="lead" data-edit>权重矩阵</p><p data-edit>大量数字组成的参数</p><p data-edit>运行时，由计算过程使用</p><p class="fine" data-edit>下载包也包含 config 等配置文件。</p></div><figure><img src="'+img(6)+'" alt="权重矩阵与Raw Model原始板书"><figcaption>原课板书：计算过程与权重相连</figcaption></figure></div>',6,'区分函数抽象与下载文件。原课提到几个G、几十G、几百G乃至一个T的体积，但参数个数与存储字节不是同一个单位。')
add('7B，说的是参数个数','<div class="equation"><b>7B</b><span>=</span><strong>70 亿</strong></div><p class="takeaway" data-edit>权重中的数字有多少，就有多少参数。</p><div class="unit-strip"><span>B = billion = 十亿</span><span>T = trillion = 万亿</span></div>',6,'保留7B、16B与商用部署的原课对比。原讲者提及“GPT-5还是什么模型超过10T”，其记忆明确不确定；完整教程保留原话，本页不将其写成确定的产品规格。')
add('训练与微调，改变的是权重','<div class="comparison"><div><em>训练</em><p data-edit>从无到有</p><strong data-edit>得到权重矩阵</strong></div><div><em>微调</em><p data-edit>已有权重</p><strong data-edit>继续训练并调整</strong></div></div><p class="takeaway" data-edit>从外部理解概念，不展开内部算法。</p>',7,'原课把训练概括为从无到有，微调概括为对已有矩阵做二次训练和改动。这里保持课程的外部观察视角。')
add('语料是训练的原材料','<div class="corpus"><div>中文 / 英文 / 代码</div><b>→</b><div>训练 / 微调</div><b>→</b><div>权重矩阵</div></div><div class="pullquote" data-edit>见过足够多的 Token，<br>预测才可能更合理。</div><p class="fine" data-edit>原课案例：开源库为编程模型提供大量代码语料。</p>',7,'接回模型的预测任务：输入Token列表，输出下一个Token的概率分布。原课用庞大的开源库解释编程模型的语料来源，保留“主要因为”的讲者解释，不扩展为能力的完整归因。')
add('架构规定怎样使用权重','<div class="assembly"><div>输入 Token</div><b>+</b><div>权重参数</div><b>+</b><div class="highlight">架构与算法</div></div><div class="result-line">↓<p data-edit>下一个 Token 的概率分布</p></div><p class="fine" data-edit>本课围绕 Transformer、神经网络与深度学习展开。</p>',8,'原课提及通过Hugging Face库调用模型，并强调训练架构与调用方式相配。板书另写“Tensor架构”，所指没有明确展开，完整教程保留，讲授时不要把它补充成已验证的架构分类。其他AI技术不一定适用这一套描述。')
add('先建立数学函数的直觉','<div class="math-function"><span>输入</span><b>f<sub>θ</sub>(x)</b><span>输出分布</span></div><p class="takeaway" data-edit>在固定权重的数学抽象下，输入决定计算结果。</p><p class="fine" data-edit>原课以“纯函数”作比喻，随后补充实际运行的浮点误差。</p>',9,'继续复述原课的1+2=3类比和对AI拟人化的评论。将“自我意识、感情”等保留为原讲者观点；单凭函数形式不展开哲学结论。本页讲计算结果，不把它等同于完整聊天系统每次的文字回答。')
add('GPU 计算还要面对浮点数','<div class="split formula-layout"><div class="formula"><code>0.1 + 0.2 + 0.3</code><strong>0.6000000000000001</strong><code>0.1 + (0.2 + 0.3)</code><strong>0.6</strong><p data-edit>改变结合顺序，结果可能变化。</p></div><figure><img src="'+img(10)+'" alt="原课控制台浮点演示"><figcaption>原课控制台：两式比较为 false</figcaption></figure></div>',10,'参数多、运算量大，因此使用GPU并行计算。原课解释拆分、计算、合并，并以浮点不满足结合律说明误差。保留讲者关于旧知识在新场景里派上用场的感想。')
add('多模态，也先转成数字','<div class="modalities"><span>文字</span><span>图像</span><span>音频</span><span>视频</span></div><div class="result-line">↓<p data-edit>数字表征 → 模型计算 → 输出解释</p></div><p class="fine" data-edit>本课用 500008 → image_file 作简化示意，具体内部机制没有展开。</p>',11,'保留原课“它知道什么叫自然语言吗”的重复提问，以及“里面没有那么简单”的限定。图像编号是随手举例，不是通用标准；讲者用字典区间和转码解释如何识别输出类型，不能推广成所有多模态模型的统一流程。')
add('把概念放回同一张图',diagram(True),12,'按原课程顺序复盘：输入列表的容量是上下文；权重包含参数；语料经过训练或微调得到权重；计算使用GPU；输出是概率分布。原课以这个层次解释其“底层体系没有本质变化”的观点。','map')
add('下一层：模型服务','<div class="closing-stack"><div>模型服务<small data-edit>如何基于底层能力提供上层功能？</small></div><span>↑</span><div class="base-layer">Raw Model<small>Token 列表 → 概率分布</small></div></div><p class="fine" data-edit>先理解这一层，再进入下一课。</p>',12,'呼应原课结尾：不同语料、不同矩阵、不同上下文能力，仍在本课给出的抽象图内理解。然后进入模型服务一层。','closing')
